#include <iostream>
#include <memory>
#include <utility>
#include <new>

class Tramo {
public:
    Tramo() = default;
    Tramo(const Tramo& otra);
    Tramo& operator=(const Tramo& otra);
    Tramo(Tramo&& otra) noexcept;
    Tramo& operator=(Tramo&& otra) noexcept;
    ~Tramo() = default;
    int cantidad() const noexcept { return cantidad_; }
    const int* acceso() const noexcept { return datos_.get(); }
    bool configurar(int cantidad) noexcept;
    bool leer(int indice, int& resultado) const noexcept;
    bool escribir(int indice, int valor) noexcept;
    bool vaciar() noexcept;
    int sumar() const noexcept;
    void intercambiar(Tramo& otra) noexcept;
private:
    std::unique_ptr<int[]> datos_{};
    int cantidad_ = 0;
};
Tramo::Tramo(const Tramo& otra) : datos_{}, cantidad_{0} {
    if (otra.cantidad_ != 0) {
        datos_ = std::make_unique<int[]>(otra.cantidad_);
        for (int i = 0; i < otra.cantidad_; ++i) {
            datos_[i] = otra.datos_[i];
        }
        cantidad_ = otra.cantidad_;
    }
}
Tramo::Tramo(Tramo&& otra) noexcept
    : datos_{std::move(otra.datos_)}, cantidad_{otra.cantidad_} {
    otra.cantidad_ = 0;
}

Tramo& Tramo::operator=(const Tramo& otra) {
    if (this != &otra) {
        Tramo candidata{otra};
        intercambiar(candidata);
    }

    return *this;
}

Tramo& Tramo::operator=(Tramo&& otra) noexcept {
    if (this != &otra) {
        datos_ = std::move(otra.datos_);
        cantidad_ = otra.cantidad_;
        otra.cantidad_ = 0;
    }

    return *this;
}

bool Tramo::configurar(int cantidad) noexcept {
    if (cantidad < 0 || cantidad > 4) {
        return false;
    }
    if (cantidad == 0) {
        return vaciar();
    }
    try {
        auto candidata = std::make_unique<int[]>(cantidad);
        datos_.swap(candidata);
        cantidad_ = cantidad;
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Tramo::leer(int indice, int& resultado) const noexcept {
    if (indice < 0 || indice >= cantidad_) {
        return false;
    }
    resultado = datos_[indice];
    return true;
}

bool Tramo::escribir(int indice, int valor) noexcept {
    if (indice < 0 || indice >= cantidad_ || valor < 0 || valor > 9) {
        return false;
    }
    datos_[indice] = valor;
    return true;
}

bool Tramo::vaciar() noexcept {
    datos_.reset();
    cantidad_ = 0;
    return true;
}

int Tramo::sumar() const noexcept {
    int suma = 0;
    for (int i = 0; i < cantidad_; ++i) {
        suma += datos_[i];
    }

    return suma;
}

void Tramo::intercambiar(Tramo& otra) noexcept {
    datos_.swap(otra.datos_);
    std::swap(cantidad_, otra.cantidad_);
}

Tramo copia_modificada(const Tramo& origen, int indice, int valor) {
    // El llamador ya comprobó que indice y valor son válidos.
    (void)origen;
    (void)indice;
    (void)valor;
    return Tramo{};
}

bool tomar_si_cabe(Tramo& destino, Tramo&& origen, int limite) noexcept {
    // Comprueba el límite antes de decidir si consumes el origen ofrecido.
    (void)destino;
    (void)origen;
    (void)limite;
    return false;
}

void mostrar(const Tramo& lote) {
    std::cout << lote.cantidad() << '[';
    for (int i = 0; i < lote.cantidad(); ++i) {
        int valor = -1;
        lote.leer(i, valor);
        if (i != 0) {
            std::cout << ',';
        }
        std::cout << valor;
    }
    std::cout << ']';
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Tramo tramos[2];
    if (!tramos[0].configurar(3) || !tramos[1].configurar(1)) { return 1; }
    tramos[0].escribir(0, 1);
    tramos[0].escribir(2, 4);
    tramos[1].escribir(0, 8);
    for (int i = 0; i < ordenes; ++i) {
        int op = 0, destino = 0, a = 0, b = 0, c = 0;
        if (!(std::cin >> op >> destino >> a >> b >> c)) { return 1; }
        std::cout << "Antes:A="; mostrar(tramos[0]);
        std::cout << ";B="; mostrar(tramos[1]);
        bool aceptado = false;

        if (destino >= 0 && destino < 2) {
            Tramo& actual = tramos[destino];
            if (op == 1 && a >= 0 && a < 2) {
                const Tramo& origen = tramos[a];
                if (b >= 0 && b < origen.cantidad() && c >= 0 && c <= 9) {
                    try {
                        actual = copia_modificada(origen, b, c);
                        aceptado = true;
                    } catch (const std::bad_alloc&) {
                        aceptado = false;
                    }
                }
            } else if (op == 2 && a >= 0 && a < 2) {
                aceptado = tomar_si_cabe(actual, std::move(tramos[a]), b);
            } else if (op == 3) {
                aceptado = actual.escribir(a, b);
            } else if (op == 4) {
                aceptado = actual.configurar(a);
            }
        }
        std::cout << ";Aceptado:" << aceptado << ";Ahora:A=";
        mostrar(tramos[0]); std::cout << ";B="; mostrar(tramos[1]);
        std::cout << '\n';
    }
    std::cout << "Sumas:" << tramos[0].sumar() << ':' << tramos[1].sumar();

    return 0;
}

